after:
- name: Run Normal E2E Tests
  id: run_tests
  shell: bash
  run: node scripts/run-main-verification.mjs "$TEST_SUITE" "$TEST_BROWSER" "$TEST_OS" tests
  env:
    TEST_SUITE: normal
    TEST_BROWSER: ${{ matrix.browser }}
    TEST_OS: ${{ matrix.os }}
    TEST_SCOPE: ${{ inputs.test_scope || 'all' }}
    TEST_WORKERS: ${{ github.event.inputs.workers }}
    TEST_RETRIES: ${{ inputs.retries || '0' }}
    PWAPPY_WEBMCP_LIVE_PREMIUM_AUTHORIZED_SHA: ${{ vars.PWAPPY_WEBMCP_LIVE_PREMIUM_AUTHORIZED_SHA }}
    PWAPPY_TEST_BASE_URL: ${{ secrets.PWAPPY_TEST_BASE_URL }}
    PWAPPY_TEST_LOGIN_ENDPOINT: ${{ secrets.PWAPPY_TEST_LOGIN_ENDPOINT }}
    PWAPPY_TEST_LOGIN_PASSCODE: ${{ secrets.PWAPPY_TEST_LOGIN_PASSCODE }}

- name: Run Local Cleanup on Finish
  timeout-minutes: 5
  if: always() && steps.run_tests.outputs.started == 'true' && steps.run_tests.outputs.state_dir != ''
  shell: bash
  run: node scripts/run-main-verification.mjs "$TEST_SUITE" "$TEST_BROWSER" "$TEST_OS" cleanup
  env:
    TEST_SUITE: normal
    TEST_BROWSER: ${{ matrix.browser }}
    TEST_OS: ${{ matrix.os }}
    TEST_SCOPE: ${{ inputs.test_scope || 'all' }}
    TEST_WORKERS: ${{ github.event.inputs.workers }}
    TEST_RETRIES: ${{ inputs.retries || '0' }}
    PWAPPY_MAIN_STATE_DIR: ${{ steps.run_tests.outputs.state_dir }}
    PWAPPY_WEBMCP_LIVE_PREMIUM_AUTHORIZED_SHA: ${{ vars.PWAPPY_WEBMCP_LIVE_PREMIUM_AUTHORIZED_SHA }}
    PWAPPY_TEST_BASE_URL: ${{ secrets.PWAPPY_TEST_BASE_URL }}
    PWAPPY_TEST_LOGIN_ENDPOINT: ${{ secrets.PWAPPY_TEST_LOGIN_ENDPOINT }}
    PWAPPY_TEST_LOGIN_PASSCODE: ${{ secrets.PWAPPY_TEST_LOGIN_PASSCODE }}

